BEGIN;
CREATE TABLE "ReceiptObservation" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"siteId" UUID NOT NULL,"receiptId" UUID NOT NULL,"lineId" UUID NOT NULL,"version" INTEGER NOT NULL CHECK("version">0),"snapshot" JSONB NOT NULL CHECK(jsonb_typeof("snapshot")='object'),"recordedAt" TIMESTAMPTZ(3) NOT NULL,UNIQUE("tenantId","siteId","receiptId","lineId"),UNIQUE("id","tenantId","siteId"),FOREIGN KEY("receiptId","tenantId","siteId") REFERENCES "ReceiptDraft"("id","tenantId","siteId") ON DELETE RESTRICT);
CREATE INDEX "ReceiptObservation_tenantId_siteId_receiptId_idx" ON "ReceiptObservation"("tenantId","siteId","receiptId");
CREATE TABLE "ReceiptObservationRevision" ("observationId" UUID NOT NULL,"tenantId" UUID NOT NULL,"siteId" UUID NOT NULL,"version" INTEGER NOT NULL CHECK("version">0),"actorId" UUID NOT NULL,"sessionId" UUID NOT NULL,"correlationId" UUID NOT NULL,"recordedAt" TIMESTAMPTZ(3) NOT NULL,"snapshot" JSONB NOT NULL CHECK(jsonb_typeof("snapshot")='object'),PRIMARY KEY("observationId","version"),FOREIGN KEY("observationId","tenantId","siteId") REFERENCES "ReceiptObservation"("id","tenantId","siteId") ON DELETE RESTRICT);
CREATE INDEX "ReceiptObservationRevision_tenantId_siteId_observationId_idx" ON "ReceiptObservationRevision"("tenantId","siteId","observationId");
CREATE TABLE "ReceiptObservationOperation" ("tenantId" UUID NOT NULL,"siteId" UUID NOT NULL,"actorId" UUID NOT NULL,"operationId" UUID NOT NULL,"intentHash" CHAR(64) NOT NULL,"snapshot" JSONB NOT NULL CHECK(jsonb_typeof("snapshot")='object'),"recordedAt" TIMESTAMPTZ(3) NOT NULL,PRIMARY KEY("tenantId","siteId","actorId","operationId"));
CREATE TRIGGER "ReceiptObservationRevision_append_only" BEFORE UPDATE OR DELETE ON "ReceiptObservationRevision" FOR EACH ROW EXECUTE FUNCTION reject_receipt_draft_history_change();
CREATE TRIGGER "ReceiptObservationOperation_append_only" BEFORE UPDATE OR DELETE ON "ReceiptObservationOperation" FOR EACH ROW EXECUTE FUNCTION reject_receipt_draft_history_change();
COMMIT;
